-- Gercek, idempotent editorial baslangic icerigi ve sureli soru havuzu.
alter table public.topics alter column user_id drop not null;alter table public.answers alter column user_id drop not null;
alter table public.topics add column if not exists is_editorial boolean not null default false,add column if not exists editorial_key text,add column if not exists editorial_label text;
alter table public.answers add column if not exists is_editorial boolean not null default false,add column if not exists editorial_key text,add column if not exists editorial_label text;
create unique index if not exists topics_editorial_key_uidx on public.topics(editorial_key) where editorial_key is not null;create unique index if not exists answers_editorial_key_uidx on public.answers(editorial_key) where editorial_key is not null;
alter table public.topics drop constraint if exists topics_editorial_owner_check;alter table public.topics add constraint topics_editorial_owner_check check((is_editorial and user_id is null and editorial_key is not null) or (not is_editorial and user_id is not null and editorial_key is null));
alter table public.answers drop constraint if exists answers_editorial_owner_check;alter table public.answers add constraint answers_editorial_owner_check check((is_editorial and user_id is null and editorial_key is not null) or (not is_editorial and user_id is not null and editorial_key is null));

drop policy if exists topics_insert on public.topics;create policy topics_insert on public.topics for insert to authenticated with check(user_id=auth.uid() and status='pending' and is_editorial=false and editorial_key is null);
drop policy if exists answers_insert_audience on public.answers;create policy answers_insert_audience on public.answers for insert to authenticated with check(user_id=auth.uid() and status='pending' and is_editorial=false and editorial_key is null and exists(select 1 from public.topics t join public.profiles p on p.id=auth.uid() where t.id=topic_id and t.status='published' and (not t.is_timed or t.expires_at>now()) and (t.audience='all' or t.audience=p.gender)));
drop policy if exists votes_insert on public.answer_votes;create policy votes_insert on public.answer_votes for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.answers a where a.id=answer_id and a.status='published' and (a.user_id is null or a.user_id<>auth.uid())));

with seed(key,cat,title,body,audience,label,a1,a2) as (values
('futbol-01','futbol','Galatasaray’ın bu sezon en büyük eksiği sizce ne?','Kadro güçlü görünüyor ama bazı maçlarda oyun kolayca kopuyor. Eksik olan sizce oyuncu profili mi, oyun planı mı?','all','ANLATI Futbol','Bence sorun orta sahadan çok geçiş savunması. Top kaybından sonra takımın boyu fazla uzuyor.','Bir de sabit on bir meselesi var. Rotasyon gerekli ama oyuncuların birbirini ezberlemesi de gerekiyor.'),
('futbol-02','futbol','Derbi öncesi orta saha mı savunma mı daha kritik?','Büyük maçlarda oyunun hangi bölgede kazanıldığını düşünüyorsunuz?','all','ANLATI Futbol','Orta sahayı kaybedince savunma ne kadar iyi olursa olsun sürekli baskı yiyor.','Derbide ilk hata pahalıya patlıyor; ben savunma konsantrasyonunu öne koyarım.'),
('futbol-03','futbol','Türkiye’de tribün kültürü neden eskisi kadar güçlü değil?','Bilet fiyatı, yayınlar ve değişen taraftar alışkanlıkları bunda ne kadar etkili?','all','ANLATI Futbol','Fiyatlar ve ulaşım ciddi etken. Maça gitmek artık spontane bir hafta sonu planı değil.','Tribün gruplarının dili de değişti; yeni taraftar kendini her zaman o kültüre ait hissetmiyor.'),
('futbol-04','futbol','Bir futbol takımını gerçekten büyük yapan şey nedir?','Kupa sayısı mı, taraftarı mı, tarihi mi; sizin ölçünüz ne?','all','ANLATI Futbol','Sadece kupa değil, kötü dönemde de ayakta kalan kurum kültürü bence.','Avrupa’da bıraktığı iz ve nesiller boyunca aktarılan taraftarlık daha belirleyici.'),
('futbol-05','futbol','Maçı statta izlemek mi televizyonda izlemek mi?','Atmosfer ile oyunu ayrıntılı takip etmek arasında hangisini seçersiniz?','all','ANLATI Futbol','Önemli maç statta; taktik izlemek istediğim maç evde. İkisinin keyfi başka.','Statta tekrar yok ama o ses ve ortak heyecan televizyonda oluşmuyor.'),
('otomobil-01','otomobil-motosiklet','900 bin TL bütçeyle bugün hangi ikinci el araba alınır?','Otomatik, makul tüketimli ve parçası kolay bulunan bir araç arayan biri nereden başlamalı?','all','ANLATI Otomobil','Modelden önce temiz geçmişe bakardım. Ekspertiz ve bakım kaydı bu bütçede donanımdan önemli.','Piyasası hızlı diye istemediğin aracı alma; üç yıl kullanacağın için sürüş pozisyonunu da dene.'),
('otomobil-02','otomobil-motosiklet','Dizel araç hâlâ mantıklı mı?','Yıllık kilometre ve bakım maliyeti düşünüldüğünde dizel kimler için doğru seçim?','all','ANLATI Otomobil','Yılda 25 bin kilometre ve uzun yol varsa hâlâ hesabı yapılabilir. Şehir içi kısa mesafede zor.','İkinci elde DPF ve enjektör geçmişini bilmeden yakıt tasarrufu kâğıt üzerinde kalabilir.'),
('otomobil-03','otomobil-motosiklet','İlk arabasını alacak birine ne önerirsiniz?','Yeni sürücünün bütçe dışında özellikle dikkat etmesi gereken şeyler neler?','all','ANLATI Otomobil','Görüş açıları iyi, ölçüleri kolay öğrenilen bir otomobil büyük rahatlık sağlar.','Sigorta, lastik ve ilk bakım için satın alma bütçesinden ayrıca pay bırakmak gerek.'),
('otomobil-04','otomobil-motosiklet','Manuel mi otomatik mi?','Yoğun şehir trafiği dışında manuel şanzımanın hâlâ anlamlı bir avantajı var mı?','all','ANLATI Otomobil','Her gün trafikteysen otomatik verdiğin farkı konforla geri ödüyor.','Keyif otomobili ayrı konu ama tek araç olacaksa günün şartlarında otomatik daha mantıklı.'),
('otomobil-05','otomobil-motosiklet','Araba alırken kilometre mi yaş mı daha önemli?','Düşük kilometreli yaşlı araç ile genç ama çok kullanılmış araç arasında nasıl karar verilir?','all','ANLATI Otomobil','Bakım geçmişi ikisinden de önemli. Düzenli uzun yol kilometresi, bakımsız düşük kilometreden iyi olabilir.','Yaşla kauçuk ve plastik parçalar yoruluyor; sadece kilometreye güvenmem.'),
('kadin-01','kadinlara-sor','Bir kadın gerçekten ilgisini kaybettiğinde nasıl davranır?','Mesajların seyrekleşmesi tek başına bir işaret midir? Kadınların görüşünü merak ediyoruz.','female','ANLATI Yaşam','Tek bir davranıştan sonuç çıkarmak zor. Çaba sürekli tek taraftan geliyorsa açıkça konuşmak gerekir.','İlgi kaybında merak azalıyor; gününün nasıl geçtiğini sormak bile görev gibi gelmeye başlayabiliyor.'),
('kadin-02','kadinlara-sor','Bir erkekte ilk dikkat ettiğiniz şey nedir?','Görünüşten önce veya sonra sizde iz bırakan ayrıntı hangisi?','female','ANLATI Yaşam','İnsanlara nasıl davrandığı. Özellikle kendisine hizmet eden birine karşı tavrı çok şey anlatıyor.','Konuşurken gerçekten dinlemesi ve kendini kanıtlama çabasına girmemesi dikkatimi çeker.'),
('kadin-03','kadinlara-sor','İlk buluşmada fazla konuşan erkek itici gelir mi?','Heyecanla çok konuşmak ile karşı tarafa alan bırakmamak arasındaki çizgi nerede?','female','ANLATI Yaşam','Heyecan anlaşılır ama soru sormadan sürekli kendini anlatıyorsa yorucu oluyor.','Konuşkan olmak sorun değil; verdiğim cevabı takip edip etmediği daha önemli.'),
('kadin-04','kadinlara-sor','Erkeklerin ilişkilerde en sık yaptığı hata ne?','Tek bir davranış seçmeniz gerekse hangisini söylerdiniz?','female','ANLATI Yaşam','Sorunu çözmeye çalışırken duyguyu atlamaları. Bazen önce anlaşılmış hissetmek gerekiyor.','Rahatsız olduğu şeyi zamanında söylemeyip sonra birikmiş şekilde ortaya dökmek.'),
('erkek-01','erkeklere-sor','40 yaşından sonra spora başlayan var mı?','Sıfırdan başlayanlar ilk aylarda neyi farklı yapmayı isterdi?','male','ANLATI Yaşam','Ağırlığı değil devamlılığı hedeflemek gerek. İlk ay gereksiz zorlayıp iki hafta ara verdim.','Uyku ve hareketlilik çalışması bu yaşta programın süsü değil, temeli.'),
('erkek-02','erkeklere-sor','Bir erkek zor zamanlarında gerçekten konuşmak ister mi?','Susmak ihtiyaç mı, konuşacak güvenli alan bulamamak mı?','male','ANLATI Yaşam','Konuşmak istiyor ama hemen çözüm ya da yargı duymaktan çekinebiliyor.','Bazen önce kendi içinde adını koyması zaman alıyor. Sessizlik her zaman uzaklaşmak değil.'),
('erkek-03','erkeklere-sor','İş değiştirme kararında para mı huzur mu ağır basar?','Maaş farkı hangi noktada risk almaya değer?','male','ANLATI Yaşam','Huzursuzluğun kaynağı yöneticiyse yüzde yirmi fark bile tek başına yetmeyebilir.','Yeni işte öğrenme ve ilerleme alanı varsa kısa vadeli maaş farkından daha değerli olabilir.'),
('erkek-04','erkeklere-sor','Özgüven ile ego arasındaki çizgi sizce nerede?','Kendinden emin olmak ne zaman çevreyi küçümsemeye dönüşüyor?','male','ANLATI Yaşam','Özgüven hata yaptığını söyleyebilir; ego sürekli haklı çıkmak ister.','Başkasının başarısı seni tehdit ediyorsa orada özgüvenden uzaklaşılmıştır.'),
('is-01','is-para','Yüksek maaş mı iyi çalışma ortamı mı?','İkisini aynı anda bulamadığınız bir dönemde hangisini seçtiniz?','all','ANLATI Editör','Maddi hedef için süre koyup yüksek maaş seçilebilir, ama süresiz kötü ortam insanı tüketiyor.','İyi ekipte öğrendiğim şeyler sonraki maaşımı da yükseltti; uzun vadede ortam kazandı.'),
('is-02','is-para','Ek gelir için bugün hangi beceriyi öğrenirdiniz?','Altı ay düzenli zaman ayırabilecek biri için gerçekçi öneriniz ne olur?','all','ANLATI Editör','Satış ve iyi yazma, sektör değişse de değerini koruyor. Teknik beceriyi görünür kılıyor.','Veri analizi öğrenirdim ama önce kendi işimde çözeceğim gerçek bir problem seçerdim.'),
('is-03','is-para','Bir işte ne zaman artık gitme zamanı gelmiştir?','Zor dönem ile kalıcı kötü düzeni nasıl ayırt ediyorsunuz?','all','ANLATI Editör','Aynı sorun konuşulduğu hâlde altı ay boyunca hiçbir şey değişmiyorsa sinyal güçlü.','Pazar sabahı bile pazartesi kaygısı yaşıyorsan bedeni de dinlemek gerekiyor.'),
('tatil-01','tatil-gezi','İlk kez tek başına tatile çıkacak biri nereye gitmeli?','Güvenli, ulaşımı kolay ve yalnız hissettirmeyen bir rota arıyoruz.','all','ANLATI Yaşam','İlk denemeyi üç-dört gün ve ulaşımı kolay bir sahil kentinde yapmak baskıyı azaltır.','Programı tamamen doldurma; tek başına tatilin en iyi yanı karar değiştirebilmek.'),
('teknoloji-01','teknoloji-oyun','Telefonu kaç yılda bir değiştirmek gerçekten mantıklı?','Pil dışında günlük kullanımı etkileyen sorun yoksa yükseltmeye gerek var mı?','all','ANLATI Teknoloji','Güvenlik güncellemesi aldığı ve pil değişebildiği sürece dört yıl rahat kullanılır.','Kamera iş için gerekmiyorsa yeni model heyecanı birkaç haftada geçiyor.'),
('spor-01','spor-fitness','Haftada üç gün sporla gerçekten gelişilir mi?','Yoğun çalışan biri için sürdürülebilir en basit düzen nasıl olmalı?','all','ANLATI Yaşam','Üç tam vücut antrenmanı çoğu insan için fazlasıyla yeterli. Asıl fark düzenlilikte.','Antrenman dışındaki günlük adım ve uyku da sonuç üzerinde düşündüğümüzden büyük.'),
('icimde-01','icimde-kaldi','Bazen insanın anlatacak çok şeyi oluyor ama kime anlatacağını bilmiyor.','Çözüm aramadan, yalnızca içimde kalan bir duyguyu bir yere bırakmak istedim.','all','ANLATI Editör','Her şeyi tek seferde anlatmak zorunda değilsin. Bir cümleyle başlamak da başlangıç.','Dinlenmek bazen tavsiyeden daha değerli. Burada yargılanmadan anlatabilirsin.'),
('tatil-02','tatil-gezi','Deniz tatili mi doğa tatili mi?','Bir haftalık gerçek dinlenme için hangisi sizi daha iyi toparlıyor?','all','ANLATI Yaşam','Deniz daha zahmetsiz geliyor; birkaç gün sonra gerçekten yavaşladığımı hissediyorum.','Doğada telefon ve kalabalıktan uzaklaşmak bende daha kalıcı bir dinlenme yaratıyor.'),
('stil-01','stil-bakim','İyi bir günlük ayakkabıya ne kadar bütçe ayrılır?','Şık, rahat ve uzun ömürlü bir ayakkabıda fiyat ile kalite dengesi nerede başlıyor?','all','ANLATI Yaşam','Her gün giyilecekse kullanım başına maliyet düşük oluyor; taban ve deri kalitesine bakarım.','Markadan önce kalıp önemli. Çok iyi ayakkabı bile ayağa uymuyorsa dolapta kalıyor.'),
('baba-01','baba-aile','Baba olduktan sonra hayatınızda en çok ne değişti?','Hazırlıklı olduğunuzu sandığınız hâlde sizi şaşırtan şey neydi?','male','ANLATI Yaşam','Zamanın değeri değişti. Bir saatlik boşluk bile eskisinden çok daha kıymetli geliyor.','Sorumluluk arttı ama küçük şeylerden aldığım sevinç de beklemediğim kadar büyüdü.'),
('hayat-01','hayat','Yeni bir başlangıç için doğru zaman gerçekten var mı?','İş, şehir veya düzen değiştirmek için emin olmayı beklemek gerekir mi?','all','ANLATI Yaşam','Tam emin olunan bir an gelmiyor. Riski küçültüp ilk adımı atmak daha gerçekçi.','Kaçmakla yön değiştirmeyi ayırmak gerek; neye doğru gittiğini biliyorsan zaman yaklaşmıştır.'),
('icimde-02','icimde-kaldi','Geç kaldığımı düşündüğüm şeyler var.','Başkalarının hayatına bakınca kendi yolumda geride kalmış gibi hissediyorum.','all','ANLATI Editör','Herkesin takvimi başka. Dışarıdan gördüğümüz sonuçların arkasındaki yolu bilmiyoruz.','Geç kalmışlık hissi bazen ne istediğini fark ettiğinin işareti; buradan küçük bir adım çıkabilir.')
),ins as(insert into public.topics(user_id,category_id,title,body,slug,audience,status,is_editorial,editorial_key,editorial_label,created_at) select null,c.id,s.title,s.body,'editorial-'||s.key,s.audience,'published',true,s.key,s.label,now()-(row_number() over())*interval '37 minutes' from seed s join public.categories c on c.slug=s.cat on conflict(editorial_key) where editorial_key is not null do nothing returning id,editorial_key)
insert into public.answers(topic_id,user_id,body,status,is_editorial,editorial_key,editorial_label) select t.id,null,x.body,'published',true,t.editorial_key||'-a'||x.n,t.editorial_label from public.topics t join seed s on s.key=t.editorial_key cross join lateral(values(1,s.a1),(2,s.a2))x(n,body) on conflict(editorial_key) where editorial_key is not null do nothing;

create table if not exists public.editorial_timed_pool(id bigint generated always as identity primary key,editorial_key text unique not null,category_slug text not null,title text not null,body text not null,answer_one text not null,answer_two text not null,last_used_at timestamptz,is_active boolean not null default true);
insert into public.editorial_timed_pool(editorial_key,category_slug,title,body,answer_one,answer_two) select 'timed-'||lpad(n::text,2,'0'),(array['futbol','otomobil-motosiklet','kadinlara-sor','erkeklere-sor','teknoloji-oyun','tatil-gezi','hayat'])[((n-1)%7)+1],(array['Bu hafta sonu tek maç izleyecek olsanız hangisini seçerdiniz?','Uzun yolda benzinli mi hibrit mi daha rahat?','İlk buluşmada hesabı paylaşmak sizce doğal mı?','Kariyerde geç kaldığınızı hissettiğiniz oldu mu?','Yeni telefon yerine iyi bir bilgisayar almak daha mı mantıklı?','Üç günlük kaçamak için şehir mi doğa mı?','Bugünkü aklınızla yirmili yaşlarınıza ne söylerdiniz?'])[((n-1)%7)+1]||case when n>7 then ' — '||n::text else '' end,'Süre dolmadan deneyiminizi ve gerekçenizi paylaşın.','Benim için kararın kendisinden çok gerekçesi önemli; şartlara göre cevap değişiyor.','Tek bir doğru yok. Kendi deneyimimde küçük ayrıntılar sonucu tamamen değiştirdi.' from generate_series(1,30)n on conflict(editorial_key) do nothing;
create table if not exists public.platform_settings(key text primary key,value jsonb not null,updated_at timestamptz not null default now());insert into public.platform_settings(key,value) values('editorial_timed_topics','{"enabled":true,"target_active":3,"reuse_after_days":75}') on conflict(key) do nothing;

create or replace function public.refill_editorial_timed_topics() returns integer language plpgsql security definer set search_path=public as $$declare cfg jsonb;needed int;item record;topic_uuid uuid;hours int;created int:=0;begin select value into cfg from platform_settings where key='editorial_timed_topics';if not coalesce((cfg->>'enabled')::boolean,false) then return 0;end if;needed=greatest(0,coalesce((cfg->>'target_active')::int,3)-(select count(*) from topics where is_editorial and is_timed and status='published' and expires_at>now()));for item in select p.* from editorial_timed_pool p where p.is_active and (p.last_used_at is null or p.last_used_at<now()-make_interval(days=>coalesce((cfg->>'reuse_after_days')::int,75))) order by p.last_used_at nulls first,random() limit needed loop hours=(array[24,48,72])[1+floor(random()*3)::int];insert into topics(user_id,category_id,title,body,slug,audience,status,is_editorial,editorial_key,editorial_label,is_timed,timed_duration_hours,expires_at) select null,c.id,item.title,item.body,item.editorial_key||'-'||to_char(now(),'YYYYMMDDHH24'),case when item.category_slug='kadinlara-sor' then 'female' when item.category_slug='erkeklere-sor' then 'male' else 'all' end,'published',true,item.editorial_key||'-'||to_char(now(),'YYYYMMDDHH24'),'ANLATI Editör',true,hours,now()+make_interval(hours=>hours) from categories c where c.slug=item.category_slug returning id into topic_uuid;insert into answers(topic_id,user_id,body,status,is_editorial,editorial_key,editorial_label) values(topic_uuid,null,item.answer_one,'published',true,item.editorial_key||'-'||topic_uuid||'-a1','ANLATI Editör'),(topic_uuid,null,item.answer_two,'published',true,item.editorial_key||'-'||topic_uuid||'-a2','ANLATI Editör');update editorial_timed_pool set last_used_at=now() where id=item.id;created=created+1;end loop;return created;end;$$;
revoke all on function public.refill_editorial_timed_topics() from public;grant execute on function public.refill_editorial_timed_topics() to service_role;
select public.refill_editorial_timed_topics();
create extension if not exists pg_cron;
do $$declare job bigint;begin select jobid into job from cron.job where jobname='anlati-editorial-timed-refill';if job is not null then perform cron.unschedule(job);end if;perform cron.schedule('anlati-editorial-timed-refill','17 * * * *','select public.refill_editorial_timed_topics()');end$$;
